# 「深林」は 1 語、「不亦」は NEG_BU+亦 ではなく FUKI_MATA になる。
def tokenize(str)
  tokens = []
  @skipped = []
  scanner = StringScanner.new(str)
  until scanner.eos?
    if (word = scanner.scan(Kanbun::Lexicon::PATTERN))
